34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
36	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    /**
63	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
64	     * domain containing at least one dot, with no whitespace in any part.
65	     */
66	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        validateRequiredFields(ownerFieldsDto);
115	        HttpHeaders headers = new HttpHeaders();
116	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
117	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
118	        rejectDuplicateTelephone(telephone);
119	        owner.setTelephone(telephone);
120	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
121	        if (owner.getRegistrationDate() == null) {
122	            owner.setRegistrationDate(LocalDate.now());
123	        }
124	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
125	        this.clinicService.saveOwner(owner);
126	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
127	        headers.setLocation(UriComponentsBuilder.newInstance()
128	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
129	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
135	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
136	        if (currentOwner == null) {
137	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
138	        }
139	        currentOwner.setAddress(ownerFieldsDto.getAddress());
140	        currentOwner.setCity(ownerFieldsDto.getCity());
141	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
142	        currentOwner.setLastName(ownerFieldsDto.getLastName());
143	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
144	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
145	        this.clinicService.saveOwner(currentOwner);
146	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
147	    }
148	
149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Transactional
151	    @Override
152	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
153	        Owner owner = this.clinicService.findOwnerById(ownerId);
154	        if (owner == null) {
155	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
156	        }
157	        this.clinicService.deleteOwner(owner);
158	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Override
163	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
164	        Owner owner = this.clinicService.findOwnerById(ownerId);
165	        if (owner == null) {
166	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
167	        }
168	        HttpHeaders headers = new HttpHeaders();
169	        Pet pet = petMapper.toPet(petFieldsDto);
170	        owner.setId(ownerId);
171	        pet.setOwner(owner);
172	        pet.getType().setName(null);
173	        this.clinicService.savePet(pet);
174	        PetDto petDto = petMapper.toPetDto(pet);
175	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
176	            .buildAndExpand(pet.getId()).toUri());
177	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Override
182	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
183	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
184	        if (currentOwner != null) {
185	            Pet currentPet = this.clinicService.findPetById(petId);
186	            if (currentPet != null) {
187	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
188	                currentPet.setName(petFieldsDto.getName());
189	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
190	                this.clinicService.savePet(currentPet);
191	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
192	            }
193	        }
194	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
195	    }
196	
197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Override
199	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
200	        HttpHeaders headers = new HttpHeaders();
201	        Visit visit = visitMapper.toVisit(visitFieldsDto);
202	        Pet pet = new Pet();
203	        pet.setId(petId);
204	        visit.setPet(pet);
205	        this.clinicService.saveVisit(visit);
206	        VisitDto visitDto = visitMapper.toVisitDto(visit);
207	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
208	            .buildAndExpand(visit.getId()).toUri());
209	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
210	    }
211	
212	
213	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
214	    @Override
215	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
216	        Owner owner = this.clinicService.findOwnerById(ownerId);
217	        if (owner != null) {
218	            Pet pet = owner.getPet(petId);
219	            if (pet != null) {
220	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
221	            }
222	        }
223	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
224	    }
225	
226	    /**
227	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
228	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
229	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
230	     *
231	     * @param ownerFieldsDto the submitted owner fields
232	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
233	     *                                     name of every offending field
234	     */
235	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
236	        List<String> missingFields = new ArrayList<>();
237	        if (isBlank(ownerFieldsDto.getFirstName())) {
238	            missingFields.add("firstName");
239	        }
240	        if (isBlank(ownerFieldsDto.getLastName())) {
241	            missingFields.add("lastName");
242	        }
243	        if (isBlank(ownerFieldsDto.getAddress())) {
244	            missingFields.add("address");
245	        }
246	        if (isBlank(ownerFieldsDto.getCity())) {
247	            missingFields.add("city");
248	        }
249	        if (isBlank(ownerFieldsDto.getTelephone())) {
250	            missingFields.add("telephone");
251	        }
252	        if (!missingFields.isEmpty()) {
253	            throw new InvalidOwnerFieldsException(missingFields);
254	        }
255	    }
256	
257	    private boolean isBlank(String value) {
258	        return value == null || value.isBlank();
259	    }
260	
261	    /**
262	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
263	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
264	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
265	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
266	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
267	     *
268	     * @param telephone the raw telephone value submitted by the client
269	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
270	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
271	     *                                     400 response
272	     */
273	    private String normalizeTelephone(String telephone) {
274	        String e164 = toE164(telephone);
275	        if (e164 == null) {
276	            throw new InvalidOwnerFieldsException(List.of("telephone"));
277	        }
278	        return e164;
279	    }
280	
281	    /**
282	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
283	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
284	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
285	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits.
286	     *
287	     * @param telephone the raw telephone value, possibly {@code null}
288	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
289	     */
290	    private String toE164(String telephone) {
291	        if (telephone == null) {
292	            return null;
293	        }
294	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
295	        boolean hasPlus = cleaned.startsWith("+");
296	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
297	        String nationalSignificant = hasPlus
298	            ? digits
299	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
300	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
301	            return null;
302	        }
303	        return "+" + nationalSignificant;
304	    }
305	
306	    /**
307	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
308	     * is left unset. When a value is present it must be a syntactically valid address; the stored and
309	     * returned value is that address lower-cased.
310	     *
311	     * @param email the raw email value submitted by the client, or {@code null} if omitted
312	     * @return the lower-cased email, or {@code null} if none was supplied
313	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
314	     *                                     yielding a 400 response
315	     */
316	    private String normalizeEmail(String email) {
317	        if (email == null) {
318	            return null;
319	        }
320	        if (!EMAIL_PATTERN.matcher(email).matches()) {
321	            throw new InvalidOwnerFieldsException(List.of("email"));
322	        }
323	        return email.toLowerCase(Locale.ROOT);
324	    }
325	
326	    /**
327	     * Builds the owner's {@code customerCode}, formatted {@code '<LAST3>-<NNNN>'}. {@code LAST3} is
328	     * the upper-cased first three letters of the last name, and {@code NNNN} is a global 4-digit
329	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
330	     *
331	     * @param lastName the owner's last name
332	     * @return the formatted customer code
333	     */
334	    private String generateCustomerCode(String lastName) {
335	        String letters = lastName.replaceAll("[^\\p{L}]", "");
336	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
337	        int sequence = this.clinicService.findAllOwners().size() + 1;
338	        return String.format("%s-%04d", last3, sequence);
339	    }
340	
341	    /**
342	     * Rejects creation of an owner whose E.164 telephone is already used by any other owner. Stored
343	     * telephones are converted to E.164 here as well so the comparison is independent of the format
344	     * each owner was originally saved with; a stored value that cannot form a valid E.164 number is
345	     * ignored rather than matched.
346	     *
347	     * @param telephone the E.164 telephone of the owner being created
348	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone,
349	     *                                          yielding a 409 Conflict response
350	     */
351	    private void rejectDuplicateTelephone(String telephone) {
352	        boolean inUse = this.clinicService.findAllOwners().stream()
353	            .map(Owner::getTelephone)
354	            .map(this::toE164)
355	            .anyMatch(telephone::equals);
356	        if (inUse) {
357	            throw new DuplicateOwnerTelephoneException(telephone);
358	        }
359	    }
360	}
